using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RoadConvoyTests
{
    static readonly EntityId Home=new("site:castle"),Carrier=new("created:road-carrier-0"),Job=new("request:road-supply-test");
    internal static WorldSession Start(int carriers=1,bool willing=true){var basis=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var officers=NewGameWorld.Normalize(Enumerable.Range(0,carriers).Select(n=>NewGameWorldTests.Officer("created:road-carrier-"+n,StartTemplate.Retainer,lord:"person:nobunaga")).ToArray());var req=new WorldSetupRequest(officers,[]);var preview=NewGameSetup.Preview(basis,req);Assert.True(preview.IsEligible(),string.Join(',',preview.Errors));var scenario=NewGameSetup.Confirm(basis,req,preview);var w=NewGameWorld.Create(scenario,officers,"person:nobunaga",1,NewGameWorld.CompactPersonalAuthority,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,voyageRules:VoyageExpense.Standard,economyPolicy:RoadConvoy.Policy);if(!willing)w.Characters=w.Characters.Select(c=>c.Id==Carrier?c with{WillObey=false}:c).ToArray();var s=new WorldSession(w);Send(s,NewMilitaryAction.Request);Advance(s,2);Open(s);Send(s,NewMilitaryAction.Accept);Advance(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);return s;}
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long to){while(s.Seconds<to){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(to,100000);Assert.True(s.Seconds>old);}}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}
    static void Send(WorldSession s,NewMilitaryAction a,long n=0){var w=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(new NewMilitaryInput(new("request:supply-mil/"+s.Revision),a,n){AuthorityPolicy=a==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,LedgerPolicy=a==NewMilitaryAction.Request?NewGameMilitary.LedgerIdentityContract:null,FromLedger=a==NewMilitaryAction.Request?NewGameMilitary.SourceForCurrentHouse(w):null,CycleContract=a==NewMilitaryAction.Request?NewGameMilitary.CycleForCurrentHouse(w):null},s.PlayerControl,s.Revision));}
    static EntityId Near(WorldSession s){var w=s.DiagnosticSnapshot();return BranchRoutes.GraphNodes(w).Where(n=>n.Id!="castle").Select(n=>(Site:RegionalCampaign.Site(n.Id),Distance:RegionalGround.Distance(FieldWorld.FromWorld(n.Position),NewGameMilitary.Home(w,0)))).OrderBy(q=>q.Distance).First().Site;}
    static CommandResult Assign(WorldSession s,long kg=10,EntityId? destination=null,EntityId? carrier=null,EntityId? id=null)=>s.ManageCampConvoy(new(id??Job,CampConvoyAction.Dispatch,Carrier:carrier??Carrier,RiceKg:kg){DestinationSite=destination??Near(s)},s.PlayerControl,s.Revision);
    static CampConvoyJob Current(WorldSession s,EntityId? id=null)=>FieldConvoy.Jobs(s.DiagnosticSnapshot(),s.Seconds,s.Revision+1).Single(j=>j.Terms.Id==(id??Job));
    static void Load(WorldSession s){var v=s.MilitaryEconomyView()!;Good(s.ManageMilitaryRice(new(new("request:supply-load"),v.Depot,120),s.PlayerControl,s.Revision));Send(s,NewMilitaryAction.Load,NewGameMilitary.Capacity);}
    static void March(WorldSession s,EntityId site){Good(s.ManageArmyRoad(new(new("request:supply-army/"+s.Revision),ArmyRoadAction.March,site),s.PlayerControl,s.Revision));}
    static void Meet(WorldSession s){Load(s);Good(Assign(s));March(s,Near(s));Advance(s,62);var end=s.DiagnosticSnapshot().Branches!.Journeys.Max(j=>j.Legs[^1].EndAt);Advance(s,(end/60+2)*60);}
    static void Finish(WorldSession s){for(int n=0;n<20&&Current(s).Returned==null;n++){var w=s.DiagnosticSnapshot();var moving=w.Branches!.Journeys.Where(j=>j.Actor==Carrier&&w.Tasks.Any(t=>t.Id==j.Task&&t.FinishedAt==null)).LastOrDefault();Advance(s,moving!=null?moving.Legs[^1].EndAt+60:(s.Seconds/60+1)*60+1);}Assert.NotNull(Current(s).Returned);}
    [Fact]public void DispatchDebitsRealHouseRiceAndBlocksOtherAssignments(){var s=Start();long rice=s.CommunityEconomyView()!.Accounts.HouseRice;Good(Assign(s));Assert.Equal(rice-10,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(0,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Assert.Equal(10,Current(s).CargoKg);Assert.Empty(s.DiagnosticSnapshot().Branches!.Journeys);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:conflicting-freight"),HouseFreightAction.Dispatch,Home:Home,Source:Near(s),Commodity:"wood",Quantity:1,Advance:10){Carrier=Carrier},s.PlayerControl,s.Revision).Code);}
    [Fact]public void CarrierUsesSharedLandRoadsAndWaitsForActualArmy(){var s=Start();Good(Assign(s));Advance(s,62);var w=s.DiagnosticSnapshot();Assert.Single(w.Branches!.Journeys,j=>j.Actor==Carrier);Assert.All(w.Branches.Journeys.Single(j=>j.Actor==Carrier).Legs,l=>Assert.False(NationalRoutes.Sea(l.Edge)));Advance(s,w.Branches.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt+120);Assert.Equal(10,Current(s).CargoKg);Assert.Equal(0,Current(s).DeliveredKg);Assert.Equal(0,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Assert.Equal(Near(s),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Carrier).Site);}
    [Fact]public void ActualAssemblyReceivesRiceAndCarrierReturnsWithoutDuplicatingStock(){var s=Start();Meet(s);Advance(s,s.Seconds+3600);Assert.Equal(10,Current(s).DeliveredKg);Assert.Equal(0,Current(s).CargoKg);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).Carry>0);Finish(s);Assert.Equal(0,Current(s).Returned!.ReturnedKg);var w=s.DiagnosticSnapshot();Assert.Equal(Home,w.Locations.Single(l=>l.Actor==Carrier).Site);Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w))).DiagnosticSnapshot()));}

    static long NextMinute(WorldSession s)=>(s.Seconds/60+1)*60;
    static WorldSession Blocked(bool reopen=false,bool playerAway=false){var a=Start();var w=a.DiagnosticSnapshot();var edges=BranchRoutes.GraphEdges(w).Where(e=>e.From=="castle"||e.To=="castle").Select(e=>e.Id).ToArray();w.Couriers=w.Couriers! with{Conditions=edges.SelectMany(edge=>reopen?new[]{new RoadCondition(60,edge,true),new RoadCondition(650,edge,false)}:new[]{new RoadCondition(60,edge,true)}).ToArray()};a=new WorldSession(w);Good(Assign(a));if(playerAway){Load(a);March(a,Near(a));}Advance(a,62);return a;}
    static void CancelLetter(WorldSession s,EntityId address,long meet,string id="request:supply-cancel")=>Good(s.ManageFreightLetters(new(new(id),Job,FreightLetterAction.Cancel,address,meet),s.PlayerControl,s.Revision));
    [Theory][InlineData(0)][InlineData(-1)][InlineData(101)]public void InvalidQuantityLeavesHouseAndWorldUnchanged(long kg){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Assign(s,kg).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void UnwillingRetainerCannotBeAssigned(){var s=Start(willing:false);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Assign(s).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void PrincipalCannotBeHisOwnSupplyCarrier(){var s=Start();Assert.Equal(ResultCode.NotAvailable,Assign(s,carrier:s.PlayerControl).Code);}
    [Theory][InlineData("site:castle")][InlineData("site:missing")][InlineData("site:shuri")]public void HomeUnknownOrUnreachableDestinationIsRejected(string site){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());var result=Assign(s,destination:new(site));Assert.Equal(ResultCode.NotAvailable,result.Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void DispatchIsIdempotentAndDifferentQuantityConflicts(){var s=Start();Good(Assign(s));var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,Assign(s).Code);Assert.Equal(ResultCode.IdPayloadConflict,Assign(s,11).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void CannotManuallyDeliverOrReturnRemoteCargo(){var s=Start();Good(Assign(s));var b=ContractJson.Write(s.DiagnosticSnapshot());foreach(var a in new[]{CampConvoyAction.Deliver,CampConvoyAction.Return,CampConvoyAction.StartReturn,CampConvoyAction.ReportStop})Assert.Equal(ResultCode.NotAvailable,s.ManageCampConvoy(new(new("request:remote/"+a),a,Job),s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void PhysicalCancellationBeforeDepartureRestoresOnlyActualHomeCargo(){var s=Start();long rice=s.CommunityEconomyView()!.Accounts.HouseRice;Good(Assign(s));CancelLetter(s,Home,30);Assert.Equal(rice-10,s.CommunityEconomyView()!.Accounts.HouseRice);Advance(s,29);Assert.Empty(s.DiagnosticSnapshot().FreightOperations!.Receipts);Advance(s,31);Assert.Single(s.DiagnosticSnapshot().FreightOperations!.Receipts);Assert.Equal(rice-10,s.CommunityEconomyView()!.Accounts.HouseRice);Finish(s);Assert.Equal(10,Current(s).Returned!.ReturnedKg);Assert.Equal(rice,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Empty(s.DiagnosticSnapshot().Branches!.Journeys);}
    [Fact]public void CancellationReceivedAtDestinationWaitsForActualReturn(){var s=Start();long rice=s.CommunityEconomyView()!.Accounts.HouseRice;Good(Assign(s));Advance(s,62);var j=s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier);long meet=(j.Legs[^1].EndAt/60+3)*60;CancelLetter(s,Near(s),meet);Advance(s,meet-1);Assert.Empty(s.DiagnosticSnapshot().FreightOperations!.Receipts);Advance(s,meet+1);Assert.Single(s.DiagnosticSnapshot().FreightOperations!.Receipts);Assert.Null(Current(s).Returned);Assert.Equal(10,Current(s).CargoKg);Finish(s);Assert.Equal(rice,s.CommunityEconomyView()!.Accounts.HouseRice);}
    [Fact]public void PartialReceiptThenCancellationReturnsRemainderWithoutReversingDelivery(){var s=Start();Meet(s);long delivered=Current(s).DeliveredKg;Assert.InRange(delivered,1,9);Assert.Equal(10-delivered,Current(s).CargoKg);CancelLetter(s,Near(s),s.Seconds+2);Advance(s,s.Seconds+3);Finish(s);Assert.Equal(delivered,Current(s).DeliveredKg);Assert.Equal(10-delivered,Current(s).Returned!.ReturnedKg);Assert.Equal(0,Current(s).CargoKg);}
    [Fact]public void TwoCarriersCannotFillTheSameCapacityTwice(){var s=Start(2);Load(s);Good(Assign(s,100));var other=new EntityId("request:supply-second");Good(Assign(s,100,carrier:new("created:road-carrier-1"),id:other));March(s,Near(s));Advance(s,62);long end=s.DiagnosticSnapshot().Branches!.Journeys.Max(j=>j.Legs[^1].EndAt);long moment=(end+59)/60*60;Advance(s,moment-1);long carry=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;Advance(s,moment);long actual=Current(s).DeliveredKg+Current(s,other).DeliveredKg;Assert.Equal((NewGameMilitary.Capacity-carry+100)/MilitaryEconomy.PersonSecondsPerKg,actual);Assert.InRange(NewGameMilitary.View(s.DiagnosticSnapshot()).Carry,0,NewGameMilitary.Capacity);Assert.Equal(200-actual,Current(s).CargoKg+Current(s,other).CargoKg);}
    [Fact]public void ExpiredAbsentArmySupplyReturnsUnusedGrain(){var s=Start();Good(Assign(s));Advance(s,Current(s).Terms.Until+120);Assert.NotNull(Current(s).ReturnStarted);Assert.Equal(10,Current(s).CargoKg);Finish(s);Assert.Equal(0,Current(s).DeliveredKg);Assert.Equal(10,Current(s).Returned!.ReturnedKg);}
    [Fact]public void StopReportArrivesAndPausesBeforeOpeningItsObservation(){var s=Blocked();Advance(s,120);Assert.Null(s.CampConvoyView().Single().Report);s.SetPaused(false);s.AdvanceTo(180,100000);Assert.True(s.Paused);Assert.Equal(121,s.Seconds);Assert.Null(s.CampConvoyView().Single().Report);Open(s);var report=s.CampConvoyView().Single().Report;Assert.NotNull(report);Assert.Equal(120,report.ObservedAt);Assert.Equal(10,report.Cargo);Assert.Equal(Home,report.AtSite);}
    [Fact]public void KnownFailureRetriesSameSupplyObservationAtMostThreeTimes(){var s=Blocked(playerAway:true);Advance(s,400);var papers=s.DiagnosticSnapshot().FreightOperations!.Papers.Where(p=>p.Job==Job&&p.Kind==FreightOperations.ReportKind).ToArray();Assert.Equal(3,papers.Length);Assert.All(papers,p=>{Assert.Equal(120,p.Observation!.ObservedAt);Assert.Equal(10,p.Observation.Cargo);Assert.Equal(0,p.Observation.SupplyDeliveredKg);});Assert.Null(s.CampConvoyView().Single().Report);Assert.Equal(10,Current(s).CargoKg);}
    [Fact]public void LocalRoadReopeningIsInspectedBeforeCarrierStartsAgain(){var s=Blocked(reopen:true);Advance(s,649);Assert.Single(s.DiagnosticSnapshot().Branches!.Journeys,j=>j.Actor==Carrier);Advance(s,662);Assert.Equal(2,s.DiagnosticSnapshot().Branches!.Journeys.Count(j=>j.Actor==Carrier));Assert.DoesNotContain(BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),Carrier),id=>BranchRoutes.GraphEdges(s.DiagnosticSnapshot()).Any(e=>(e.From=="castle"||e.To=="castle")&&e.Id==id));Assert.Equal(10,Current(s).CargoKg);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedOwnerDestinationOrCargoIsRejected(int kind){var s=Start();Good(Assign(s));var w=s.DiagnosticSnapshot();var e=w.CampConvoys!.Entries.Single();var t=e.Terms!;w.CampConvoys=w.CampConvoys with{Entries=[e with{Terms=kind==0?t with{Owner=new("org:takeda")}:kind==1?t with{RoadDestination=new("site:kofu")}:t with{RiceKg=99}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ReturnedCarrierCanTakeAnotherConsensualLoad(){var s=Start();Good(Assign(s));Good(s.ManageCampConvoy(new(new("request:cancel-source"),CampConvoyAction.CancelAtMeeting,Job),s.PlayerControl,s.Revision));Finish(s);Good(Assign(s,id:new("request:road-supply-again")));Assert.Equal(2,FieldConvoy.Jobs(s.DiagnosticSnapshot(),s.Seconds,s.Revision+1).Length);}
    [Fact]public void OldV16SaveKeepsBytesAndCannotAcquireRoadSupply(){var s=ArmyRoadTests.Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageCampConvoy(new(Job,CampConvoyAction.Dispatch,Carrier:new("created:freight-carrier"),RiceKg:10){DestinationSite=Near(s)},s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));}
    [Fact]public void ReportDoesNotRevealCargoUntilItIsOpened(){var s=Blocked();Advance(s,62);var before=ContractJson.Write(s.CampConvoyView());Advance(s,120);Assert.Equal(before,ContractJson.Write(s.CampConvoyView()));Assert.Null(s.CampConvoyView().Single().Report);}
    [Fact]public void DifferentClockChunksKeepSameRoadDepartureAndCargo(){var a=Start();Good(Assign(a));var b=new WorldSession(a.DiagnosticSnapshot());Advance(a,180);for(long t=b.Seconds+1;t<=180;t++)Advance(b,t);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().Branches!.Journeys),ContractJson.Write(b.DiagnosticSnapshot().Branches!.Journeys));Assert.Equal(Current(a).CargoKg,Current(b).CargoKg);Assert.Equal(RegionalCampaign.ActorPointAt(a.DiagnosticSnapshot(),Carrier,180),RegionalCampaign.ActorPointAt(b.DiagnosticSnapshot(),Carrier,180));}

    [Fact]public void DeliveredCancellationCannotLoseItsReceiptAndAcknowledgementOnLoad(){var s=Start();Good(Assign(s));CancelLetter(s,Home,30);Advance(s,30);var w=s.DiagnosticSnapshot();var ack=w.FreightOperations!.Papers.Where(p=>p.Kind==FreightOperations.AckKind).Select(p=>p.Id).ToHashSet();Assert.NotEmpty(ack);var attempts=w.Messaging.Attempts.Where(a=>ack.Contains(a.MessageId)).Select(a=>a.Id).ToHashSet();w.FreightOperations=w.FreightOperations with{Receipts=[],Papers=w.FreightOperations.Papers.Where(p=>!ack.Contains(p.Id)).ToArray()};w.Messaging.Messages=w.Messaging.Messages.Where(m=>!ack.Contains(m.Id)).ToArray();w.Messaging.Attempts=w.Messaging.Attempts.Where(a=>!attempts.Contains(a.Id)).ToArray();w.Messaging.Knowledge=w.Messaging.Knowledge.Where(k=>!ack.Contains(k.MessageId)).ToArray();w.SealedMessages=w.SealedMessages.Where(id=>!ack.Contains(id.Value)).ToArray();w.Couriers=w.Couriers! with{Missions=w.Couriers.Missions.Where(c=>!attempts.Contains(c.Attempt)).ToArray()};var error=Assert.Throws<InvalidDataException>(()=>new WorldSession(w));Assert.Contains("取消の物理到達と受領記録",error.Message);}
    [Fact]public void NewCaseCannotReceiveTheOldCasesCargo(){var s=Start();Good(Assign(s));Send(s,NewMilitaryAction.Report);Advance(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Return);Advance(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Request);Advance(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);Advance(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);Load(s);March(s,Near(s));Advance(s,62);long end=s.DiagnosticSnapshot().Branches!.Journeys.Max(j=>j.Legs[^1].EndAt);Advance(s,end+180);Assert.Equal(0,Current(s).DeliveredKg);Assert.Equal(10,Current(s).CargoKg);}
    [Fact]public void NormalCampaignBuildEnablesRoadSupplyWithoutUpgradingV16(){var seed=Start().DiagnosticSnapshot().NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"road-supply-normal-"+Guid.NewGuid().ToString("N")));var p=store.New(seed.Start,seed.Registered,seed.Selected.Value,1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,RoadConvoy.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.True(RoadConvoy.Enabled(s.DiagnosticSnapshot()));Assert.NotNull(s.DiagnosticSnapshot().ArmyRoad);Assert.NotNull(s.DiagnosticSnapshot().CampConvoys);}

    [Theory][InlineData(0)][InlineData(1)]public void ForgedTransferredQuantityOrObservationDateIsRejected(int kind){var s=Start();Meet(s);var w=s.DiagnosticSnapshot();if(kind==0){var entries=w.CampConvoys!.Entries.ToArray();int n=Array.FindIndex(entries,e=>e.Input.Action==CampConvoyAction.Deliver);entries[n]=entries[n] with{TransferredKg=entries[n].TransferredKg+1};w.CampConvoys=w.CampConvoys with{Entries=entries};}else{var papers=w.FreightOperations!.Papers.ToArray();int n=Array.FindIndex(papers,p=>p.Observation!=null);papers[n]=papers[n] with{Observation=papers[n].Observation! with{ObservedAt=0}};w.FreightOperations=w.FreightOperations with{Papers=papers};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(8)]public void ActualGenerationRecoveryKeepsCargoRiceLettersAndFuture(int phase)
    {
        var a=Start();if(phase>=7){a=Blocked();if(phase==8){Advance(a,121);Open(a);}}else if(phase>=3){Meet(a);if(phase>=4){CancelLetter(a,Near(a),a.Seconds+2);Advance(a,a.Seconds+3);if(phase>=5)Advance(a,NextMinute(a)+122);if(phase==6)Finish(a);}}else{Good(Assign(a));if(phase==1)Advance(a,62);if(phase==2){Advance(a,62);Advance(a,a.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt+120);}}
        a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"road-supply-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"supply",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("supply"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CampConvoyView()),ContractJson.Write(b.CampConvoyView()));
        var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"road-supply-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"road-supply-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}
        foreach(var q in new[]{a,b})Advance(q,q.Seconds+180);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CampConvoyView()),ContractJson.Write(b.CampConvoyView()));
    }
}
